import subprocess

# Example of a safe subprocess call with a static command
def safe_convert_command():
    try:
        # Using a static command to avoid injection risks
        subprocess.run(['convert', '-version'], check=True)
        print("ImageMagick is installed and working.")
    except subprocess.CalledProcessError:
        print("Failed to execute the convert command.")

safe_convert_command()

try:
    subprocess.run(['convert', '-version'], check=True)
    print("ImageMagick is installed and accessible.")
except subprocess.CalledProcessError:
    print("Error: ImageMagick is not installed or not accessible.")
